using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputEndToEndProof {
 static List<float[]> Read(byte[] b,int count){var rows=new List<float[]>();int at=0;for(int i=0;i<count;i++){int n=(int)BitConverter.ToSingle(b,at);var p=new float[n];Buffer.BlockCopy(b,at+4,p,0,n*4);rows.Add(p);at+=(n+1)*4;}return rows;}
 static int Main(string[] a){try{string folder=a[0],slurs=a[1];byte[] ds=File.ReadAllBytes(Path.Combine(folder,"pitches-entry-ds.bin")),bounds=File.ReadAllBytes(Path.Combine(folder,"pitches-entry-common-7954.bin")),prefs=File.ReadAllBytes(Path.Combine(folder,"pitches-entry-common-7a62.bin"));float staff=BitConverter.ToSingle(ds,0x8780),left=BitConverter.ToSingle(bounds,0),right=BitConverter.ToSingle(bounds,4);int clef=BitConverter.ToInt16(ds,0xae02+(int)staff*2),prefixCount=BitConverter.ToInt16(ds,0x80d2);var state=new InputPitchState();var tokens=InputTextLists.Pitches("TR/C4/D4/E4/F4;",state);var transaction=new InputStaffTransaction(staff,clef,left,right,BitConverter.ToSingle(ds,0x8040+(int)staff*4)/25,BitConverter.ToSingle(ds,0x8040+((int)staff+1)*4),BitConverter.ToSingle(prefs,0),BitConverter.ToSingle(prefs,16),BitConverter.ToInt16(prefs,42));transaction.Pitches(tokens,true);float duration=InputRhythmToken.Parse("E");transaction.Rhythms(InputTextLists.Rhythms("E/E/E/E;"));transaction.Marks(new float[0],new int[0]);transaction.Beams(new float[]{1,4});transaction.Slurs(new float[]{1,4});var prefix=Read(File.ReadAllBytes(Path.Combine(folder,"pitches-returned-items.bin")),prefixCount);var all=transaction.Commit(prefix);if(prefix.Count!=prefixCount)throw new Exception("Transaction modified prefix collection");var expected=Read(File.ReadAllBytes(Path.Combine(slurs,"endpoint-caller-items.bin")),all.Count);int checks=0;for(int i=0;i<all.Count;i++){if(all[i].Length!=expected[i].Length)throw new Exception("Item length "+(i+1));for(int p=0;p<all[i].Length;p++){if(BitConverter.ToInt32(BitConverter.GetBytes(all[i][p]),0)!=BitConverter.ToInt32(BitConverter.GetBytes(expected[i][p]),0))throw new Exception("Item "+(i+1)+" P"+(p+1)+": "+all[i][p]+" != "+expected[i][p]);checks++;}}Console.WriteLine("PASS complete four-note F2 construction, beam and slur: "+all.Count+" items, "+checks+" exact parameter words; preserved prefix="+prefixCount);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
